FreshUI = {}
FreshUI.name = "FreshUI"

local savedVariables

local function RoundedSkillBorders()
	RedirectTexture("esoui/art/actionbar/abilityframe64_down.dds", "FreshUI/media/ActionBar/abilityframe64_down.dds")
	RedirectTexture("esoui/art/actionbar/abilityframe64_up.dds", "FreshUI/media/ActionBar/abilityframe64_up.dds")
	RedirectTexture("/esoui/art/actionbar/backrow_abilityframe.dds", "FreshUI/media/ActionBar/backrow_abilityframe.dds")
	savedVariables.Rounded_Skill_Borders = true
end

local function SquareSkillBorders()
	RedirectTexture("esoui/art/actionbar/abilityframe64_down.dds", "FreshUI/media/ActionBar/SquareBorders/abilityframe64_down.dds")
	RedirectTexture("esoui/art/actionbar/abilityframe64_up.dds", "FreshUI/media/ActionBar/SquareBorders/abilityframe64_up.dds")
	RedirectTexture("/esoui/art/actionbar/backrow_abilityframe.dds", "FreshUI/media/ActionBar/SquareBorders/backrow_abilityframe.dds")
	savedVariables.Rounded_Skill_Borders = false
end

local function getRounded_Skill_Borders()
	return savedVariables.Rounded_Skill_Borders
end

local function setRounded_Skill_Borders(v)
	if(v == true) then
		RoundedSkillBorders()
	else
		SquareSkillBorders()
	end
end

local function getHide_Weapon_Swap()
	return savedVariables.Hide_Weapon_Swap_Icon
end

local function setHide_Weapon_Swap(v)
	if(v == true) then
		ZO_ActionBar1WeaponSwap:SetAlpha(0)
		savedVariables.Hide_Weapon_Swap_Icon = true
		else
		savedVariables.Hide_Weapon_Swap_Icon = false
	end
end

