local function initializeFreshUIAddon()

	setRounded_Skill_Borders(savedVariables.Rounded_Skill_Borders)
	setHide_Weapon_Swap(savedVariables.Hide_Weapon_Swap_Icon)
	setBackground(savedVariables.Background)
	setFreshIcons(savedVariables.FreshIcons)
	setGlossyBars(savedVariables.GlossyBars)
	setRoundedTooltips(savedVariables.RoundedTooltips)
	setFreshButtons(savedVariables.FreshButtons)

	local LAM = LibAddonMenu2
	local panelName = "FreshUIOptions"

	local panelData = {
		type = "panel",
		name = "FreshUI",
		author = "|c66ccff@Yosemite-JK|r",
		version = "1.3.0",
		registerForDefaults = true,
		registerForRefresh = true,
		slashCommand = "/freshui",
	}

	local optionsData = {
		[1] = {
			type = "description",
			text = "Changes to settings will only take effect after a complete restart of the game."
		},
		[2] = {
			type = "header",
			name = "Settings"
		},
		[3] = {
			type = "checkbox",
			name = "Rounded Skill Frames",
			tooltip = "Select style of skill frames ",
			getFunc = function() return getRounded_Skill_Borders() end,
			setFunc = function(value) setRounded_Skill_Borders(value) end,
		},
		[4] = {
			type = "checkbox",
			name = "Hide Weapon Swap Icon",
			tooltip = "Hides weapon swap icon in action bar",
			getFunc = function() return getHide_Weapon_Swap() end,
			setFunc = function(value) setHide_Weapon_Swap(value) end,
		},
		[5] = {
			type = "dropdown",
			name = "Background",
			tooltip = "Select windows background style",
			choices = {"Smooth", "Sharp", "Default"},
			getFunc = function() return getBackground() end,
			setFunc = function(value) setBackground(value) end,
		},
		[6] = {
			type = "checkbox",
			name = "FreshUI Icons",
			tooltip = "Select new or default icons",
			getFunc = function() return getFreshIcons() end,
			setFunc = function(value) setFreshIcons(value) end,
		},
		[7] = {
			type = "checkbox",
			name = "Glossy Bars",
			tooltip = "Gloss effect on attribute, target and progress bars",
			getFunc = function() return getGlossyBars() end,
			setFunc = function(value) setGlossyBars(value) end,
		},
		[8] = {
			type = "checkbox",
			name = "Rounded Tooltips",
			tooltip = "Select between rounded and square styled tooltips",
			getFunc = function() return getRoundedTooltips() end,
			setFunc = function(value) setRoundedTooltips(value) end,
		},
		[9] = {
			type = "checkbox",
			name = "FreshUI Buttons",
			tooltip = "Select new or default buttons",
			getFunc = function() return getFreshButtons() end,
			setFunc = function(value) setFreshButtons(value) end,
		}
	}

	local panel = LAM:RegisterAddonPanel(panelName, panelData)
	LAM:RegisterOptionControls(panelName, optionsData)
end

function FreshUI.OnAddOnLoaded(event, name)
	if name ~= "FreshUI" then return end
	EVENT_MANAGER:UnregisterForEvent("FreshUI", EVENT_ADD_ON_LOADED)

	local defaults = {
		Rounded_Skill_Borders = false,
		Hide_Weapon_Swap_Icon = true,
		Background = "Smooth",
		FreshIcons = true,
		GlossyBars = true,
		RoundedTooltips = true,
		FreshButtons = true
	}
	savedVariables = ZO_SavedVars:NewAccountWide('FreshUIVars', 1, nil, defaults)

	initializeFreshUIAddon()
end

EVENT_MANAGER:RegisterForEvent(FreshUI.name, EVENT_ADD_ON_LOADED, FreshUI.OnAddOnLoaded)

